import re
import pandas as pd
import numpy as np
import matplotlib.pyplot as plt

pattern = re.compile(
    r"\[T\.Med Norgespris\]:C\(treat_day, Treatment\(reference=-1\)\)\[(\-?\d+)\]\s+([\-0-9\.]+)"
)

rows = []

for line in raw_text.splitlines():
    match = pattern.search(line)
    if match:
        rows.append({
            "day": int(match.group(1)),
            "beta": float(match.group(2))
        })

df = pd.DataFrame(rows).sort_values("day")

df["effect_pct"] = (np.exp(df["beta"]) - 1) * 100

plt.figure(figsize=(11, 5))

plt.plot(
    df["day"],
    df["effect_pct"],
    lw=2
)

plt.axhline(0, color="red", linestyle="--", alpha=0.7)

plt.axvline(x=334, color = 'red')

plt.xlabel("Dager siden Norgespris")
plt.ylabel("Endring i forbruk (%)")
plt.title("Event‑study: Med Norgespris vs. Uten Norgespris")

plt.grid(alpha=0.3)
plt.tight_layout()
plt.show()
